(()=>{'use strict';const params=new URLSearchParams(location.search);let screen=params.get('screen')||'U01';const draftId=params.get('draft');if(!Catalog.some(x=>x.id===screen))screen='U01';const preview=params.has('preview');let feedback='',feedbackType='info',role='all',material=0,videoPlaying=false,playPos=0,loading=false,inputChange=false;const actorId=params.get('as')||RolePolicy.defaultActor(screen);const actor=RolePolicy.get(actorId);const current=()=>YF.view(actorId);const mutate=fn=>YF.editAs(actorId,fn);const people=()=>current().people||[];const average=(q,p='A')=>{const v=[0,1].map(t=>current().scores?.[`${q}-${t}-${p}`]);return v.every(Number.isFinite)?((v[0]+v[1])/2).toFixed(2):null};const adminReady=()=>actor.group==='admin'&&YF.readyPublish();let adminSubject='all',adminTeacher='all',monitorFilter='all';material=current().materialSub||0;const root=document.getElementById('app');const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const btn=(label,action,kind='',disabled=false,extra='')=>`<button type="button" class="${kind}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;const tag=(text,type='')=>`<span class="tag ${type}">${text}</span>`;const banner=(text,type='')=>`<div class="banner ${type}" role="status">${text}</div>`;function pageURL(id,extra={}){const q=new URLSearchParams({screen:id,as:actorId,...extra});if(YF.fixture)q.set('fixture',YF.fixture);if(preview)q.set('preview','1');return 'page.html?'+q}const go=id=>{if(!RolePolicy.canOpen(actorId,id))return note('当前岗位不能进入这个页面。请返回本人任务。','warning');location.href=pageURL(id)};const link=(id,label,kind='')=>RolePolicy.canOpen(actorId,id)?btn(label,`go:${id}`,kind):`<span class="small muted">${id==='W09'?'由管理员安排账号与岗位':id==='A01'?'由录制员完成设备检查':id==='W04'?'由教务核对后台材料':'请由负责岗位处理'}</span>`;const subjects=YF.subjects;const shape=`<div class="shape" aria-hidden="true">${'<i></i>'.repeat(9)}</div>`;const field=(name,label,value,type='text')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}"></div>`;const video=(label='评分用视频 · v1')=>`<div class="video"><label>${label}</label><div class="person" aria-hidden="true"></div>${btn(videoPlaying?'Ⅱ':'▶','play','','',`aria-label="${videoPlaying?'暂停画面示意':'播放画面示意'}"`)}<small>画面示意 · 无真实音视频文件</small></div><div class="playbar"><span>${videoPlaying?'00:48':'00:00'}</span><div class="track"></div><span>02:00</span></div>`;
function note(text,type='info'){feedback=text;feedbackType=type;render();$('#announcer').textContent=text}
function modal(title,body,confirmLabel,action,kind='primary'){const trigger=document.activeElement;const d=document.createElement('dialog');d.className='dialog';d.setAttribute('aria-labelledby','dialog-title');d.innerHTML=`<div class="dialog-body"><h2 id="dialog-title">${title}</h2>${body}<div class="actions">${btn('取消','close-dialog')}${btn(confirmLabel,action,kind)}</div></div>`;document.body.append(d);d.addEventListener('close',()=>{d.remove();if(trigger?.isConnected)trigger.focus();else if(trigger?.dataset.action)document.querySelector('[data-action="'+trigger.dataset.action+'"]')?.focus()});d.addEventListener('click',e=>{if(e.target.dataset.action==='close-dialog')d.close()});d.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[...d.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')].filter(x=>x.getClientRects().length);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}});d.showModal();d.querySelector('button')?.focus()}
function closeModal(){document.querySelector('dialog')?.close()}
function heading(title,desc='',actions=''){return `<div class="page-heading"><div><div class="eyebrow">${draftId?'新场次 · 独立草稿':screen==='U01'?'YIFENG · EXAM WORKSPACE':'第一轮播音模拟考'}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div><div class="actions">${actions}</div></div>`}
const navItems={
admin:[['U01','⌂','管理工作台'],['W01','▦','考试准备'],['W04','▤','视频与材料'],['W10','◫','全场评卷'],['W07','▥','成绩核对'],['W09','◎','账号与范围']],
academic:[['U01','⌂','教务工作台'],['W01','▦','本场准备'],['W02','≡','名单与安排'],['W03','▤','整套试卷'],['W04','▷','材料核对']],
teacher:[['U01','⌂','我的工作'],['W05','▷','我的评卷任务']],
invigilator:[['U01','⌂','我的工作'],['M01','↔','本考场签到']],
recorder:[['U01','⌂','我的工作'],['A01','◉','设备与当前人'],['A02','▷','本科录制'],['A03','▤','本机上传队列']]};
function desktop(content){const s=current();const selectedNav=['W02','W03'].includes(screen)?(actor.group==='admin'?'W01':screen):screen==='W06'?'W05':screen==='W08'?'W07':screen;return `<div class="layout"><aside class="sidebar"><div class="brand"><img src="assets/yifeng-logo.png" alt="艺风传媒"><small>${actor.label}<br>工作区</small></div><nav class="side-nav" aria-label="${actor.label}工作导航">${(navItems[actor.group]||[]).map(([id,icon,name])=>`<a href="${pageURL(id)}" class="${id===selectedNav?'active':''}"><span aria-hidden="true">${icon}</span>${name}</a>`).join('')}</nav><div class="sidebar-bottom">当前身份：${actor.name}<br>${actor.group==='teacher'?'仅本人分科任务与评分':'第一轮 · 负责范围内'}<br><br>本场与历次记录分别保存</div></aside><div class="workarea"><header class="topbar"><strong>艺风考试 / ${actor.label}工作区</strong><span><span class="avatar" aria-hidden="true">${actor.group==='teacher'?'师':actor.group==='admin'?'管':'甲'}</span>${actor.name} · ${actor.label}</span></header><main id="main" class="content" tabindex="-1">${s.offline?banner('连接已断开 · 上次同步10:24。新任务与远端提交已暂停。','warning'):''}${feedback?banner(esc(feedback),feedbackType):''}${content}</main></div></div>`}
function postSwitcher(){const s=current();return ['invigilator','recorder'].includes(actor.group)&&s.roleMonitor&&s.roleRecord?btn('切换已授权岗位','switch-post','link'):''}
function phone(title,content){const s=current();return `<div class="phone-layout"><header class="phone-top"><img src="assets/yifeng-logo.png" alt="艺风传媒"><div><strong>${title}</strong><br><span class="muted">${actor.name} · ${actor.label}</span></div></header><main class="phone-main" id="main" tabindex="-1">${s.offline?banner('网络未连接 · 当前为上次同步状态','warning'):''}${feedback?banner(esc(feedback),feedbackType):''}${content}</main>${actor.group==='student'?`<nav class="student-nav" aria-label="本人导航">${link('S00','我的考试',screen==='S00'?'active':'')}${link('S02','我的成绩',screen==='S02'?'active':'')}</nav>`:''}<footer class="phone-footer">${postSwitcher()}<br>艺风传媒 · ${actor.group==='student'?'本人考试服务':actor.label+'工作区'}</footer></div>`}
function scoreKey(s=current()){return `${s.scoreSub}-${s.teacher}-${s.student}`}
function taskStatus(q){let s=current();return people().filter(p=>Number.isFinite(s.scores[`${q}-${s.teacher}-${p.id}`])).length}
function pageU01(){const s=current();const allTasks={
admin:[['全场评卷概览','每位老师的完成情况与原始分','W10','◫'],['成绩核对与发布','缺评、按科平均与独立发布','W07','▥'],['账号与负责范围','机构账号、岗位与未完任务移交','W09','◎'],['考试准备','名单、套卷与人员安排','W01','▦'],['视频与材料','按应有名单核对评分用视频','W04','▤']],
academic:[['本场准备','本场规则、考场与缺项清单','W01','▦'],['名单与安排','同名核对、批次导入与排次','W02','≡'],['整套试卷','补齐缺科、核对本场版本','W03','▤'],['材料核对','按名单找齐材料并开放科目','W04','▷']],
teacher:[['我的评卷任务','只查看本人负责科目、已保存分数与未评任务','W05','▷']],
invigilator:[['03考场签到与候考','展示签到码、查看本考场名单与发出交接','M01','↔']],
recorder:[['设备与当前人','检查设备并接收当前学员','A01','◉'],['本机视频与上传','保留原学员原科文件，处理待传与失败','A03','▤']]};
const tasks=allTasks[actor.group]||[];const cards=tasks.map(t=>`<article class="taskcard"><div class="icon" aria-hidden="true">${t[3]}</div><h2>${t[0]}</h2><p>${t[1]}</p>${link(t[2],'进入任务 →','link')}</article>`).join('');
const draftList=['admin','academic'].includes(actor.group)&&(s.examDrafts||[]).length?`<section class="panel"><h2>待准备的考试草稿</h2>${s.examDrafts.map(d=>`<div class="listrow"><div><strong>${esc(d.name)}</strong><p>${esc(d.date)} · ${esc(d.room)}</p></div>${btn('继续准备',`edit-draft:${d.id}`,'link')}</div>`).join('')}</section>`:'';
const content=`${heading(actor.group==='teacher'?'我的评卷工作':actor.label+'工作台',actor.group==='teacher'?'当前为'+actor.name+'，仅显示本人任务和评分。':'当前工作区仅显示此岗位能处理的任务。',['admin','academic'].includes(actor.group)?btn('＋ 新建考试','new-exam'):'')}<div class="hero">${shape}<div class="eyebrow">第一轮播音模拟考</div><h2>${actor.group==='teacher'?'本科全部学员，由本人逐份评阅':'03考场 · 本场任务'}</h2><p style="margin:0">${actor.group==='teacher'?'每个科目负责全部3名学员；不显示其他老师的评分。':actor.group==='admin'?'全场进度、成绩核对与发布由管理员查看。':'按本岗位负责范围接续工作。'}</p></div>${draftList}<div class="three-col">${cards}</div>`;
return ['invigilator','recorder'].includes(actor.group)?phone('我的工作',content):desktop(content)}
function pageW01(){if(draftId)return pageExamDraft();const s=current();const issues=[!s.roster&&['名单与安排','1行同名身份待核对','W02'],!s.paper18&&['18号套卷','缺少新闻播报材料，该套暂不参与抽取','W03'],!s.assigned&&['考场人员','03考场尚未安排录制员','W09']].filter(Boolean);return desktop(`${heading('本场准备','把本场信息核对好，再交给现场工作人员。',btn('参考上场','copy-config')+btn('检查开考准备','check-prep','primary'))}<div class="tabs">${link('W01','本场安排','active')}${link('W02','名单与安排')}${link('W03','整套试卷')}${link('W09','人员与范围')}</div><div class="two-col"><div><section class="panel"><div class="panel-title"><h2>准备清单</h2>${tag(issues.length?'有'+issues.length+'项待处理':'配置已核对',issues.length?'warning':'success')}</div>${issues.length?issues.map(r=>`<div class="listrow"><div><h3>${r[0]}</h3><p>${r[1]}</p></div>${link(r[2],'去处理 →','link')}</div>`).join(''):banner('配置检查已通过。开考前还需要用实际设备完成现场检查。')}<div class="listrow"><div><h3>03考场设备</h3><p>${s.device?'本次设备检查已记录':'手机、声音与大屏需现场检查'}</p></div>${link('A01','查看检查项 →','link')}</div></section><section class="panel"><h2>本场信息</h2><div class="form-grid">${field('exam-name','考试名称',s.examName)}${field('exam-date','考试日期',s.date,'date')}</div><div class="field-hint">北京时间 · 日期为虚构样本安排</div><hr><div class="actions">${btn('保存草稿','save-prep')}<span id="prep-save" class="small muted">${s.prepared?'已保存 · 配置 v1':'草稿待核对'}</span></div></section></div><aside><section class="panel"><h2>科目与题套</h2><div class="pill-row">${subjects.map(x=>tag(x)).join('')}</div><hr><p class="small">17号套卷已完整，可用于本场。18号套卷${s.paper18?'已补齐':'尚未完整'}。</p>${link('W03','检查整套试卷 →','link')}</section><section class="panel"><h2>03考场人员</h2><dl class="kv"><dt>监考员</dt><dd>工作人员甲</dd><dt>录制员</dt><dd>${s.assigned?'工作人员甲（兼岗）':'尚未安排'}</dd><dt>材料核对</dt><dd>工作人员乙</dd></dl>${link('W09','查看岗位与范围 →','link')}</section></aside></div>`)}

function pageExamDraft(){
 const s=current(),d=(s.examDrafts||[]).find(x=>x.id===draftId);
 if(!d)return desktop(`${heading('未找到这份草稿','请返回工作台选择已保存的考试草稿。',link('U01','返回我的工作'))}`);
 return `<div class="record-layout"><header class="record-header"><img src="assets/yifeng-logo.png" alt="艺风传媒"><div><strong>考试草稿准备</strong><br><small class="muted">${esc(d.id)}</small></div>${link('U01','返回我的工作')}</header><main id="main" class="content" style="width:100%;margin:0 auto" tabindex="-1">${feedback?banner(esc(feedback),feedbackType):''}${heading(esc(d.name),'新场次分别准备名单、题目与人员，已有考试的执行记录继续保留。',btn('参考本场配置','draft-copy')+btn('保存草稿','save-exam-draft','primary'))}<div class="two-col"><section class="panel"><h2>基本安排</h2><div class="form-grid">${field('draft-name','考试名称',d.name)}${field('draft-date','考试日期',d.date,'date')}${field('draft-room','考场',d.room)}${field('draft-monitor','监考员',d.monitor||'')}${field('draft-recorder','录制员',d.recorder||'')}</div><hr><h3>本场科目</h3><div class="pill-row">${subjects.map(x=>tag(x)).join('')}</div><p class="fine">${d.copied?'已参考本场科目、考场与工作人员。':'采用三科草稿模板，后续按本场规则核对。'}</p><div class="save-status saved">✓ 草稿已保存 · 修订 ${d.revision}</div></section><aside><section class="panel"><h2>这份草稿尚需准备</h2><div class="listrow"><div><strong>名单与排次</strong><p>新场次名单未导入</p></div>${tag('待准备','warning')}</div><div class="listrow"><div><strong>本场套卷</strong><p>需另行核对选用</p></div>${tag('待准备','warning')}</div><div class="listrow"><div><strong>设备与现场</strong><p>开场前重新检查</p></div>${tag('未检查','warning')}</div></section>${banner('当前草稿没有签到、抽题、视频、评分或发布结果。参考配置不会带入旧执行状态。')}</aside></div></main></div>`;
}
function pageW02(){const s=current();return desktop(`${heading('名单与安排','导入批次 IMP-001 · 先核对身份，再保存本场安排。',link('W01','返回本场准备'))}<div class="steps"><span>1 选择名单</span><span>2 对照字段</span><span class="current">3 核对预览</span><span>4 确认导入</span></div>${s.roster?banner('本批已导入 · IMP-001 · 重复确认会返回同一结果。账号认领状态另行核实。'):banner('当前为导入预览。找到同名账号的行需要人工核对，不能只凭姓名合并。','warning')}<section class="panel"><div class="panel-title"><h2>本批3行</h2>${tag(s.identity?'身份已核对':'1行待核对',s.identity?'success':'warning')}</div><div class="table-scroll"><table><thead><tr><th>原表行</th><th>学员</th><th>本场安排</th><th>核对结果</th><th>处理</th></tr></thead><tbody><tr><td>第2行</td><td>示例学员A<small>YF-001 · 示例一班</small></td><td>03考场 · 09</td><td>${tag('已有账号可关联','success')}</td><td>保留身份</td></tr><tr class="row-highlight"><td>第3行</td><td>示例学员B<small>示例二班</small></td><td>03考场 · 07</td><td>${tag(s.identity?'已关联 YF-002':'找到两个同名账号',s.identity?'success':'warning')}</td><td>${btn(s.identity?'查看核对':'核对本行','identity','',s.roster)}</td></tr><tr><td>第4行</td><td>示例学员C<small>YF-003 · 示例一班</small></td><td>03考场 · 08</td><td>${tag('已在本场名单')}</td><td>沿用已有记录</td></tr></tbody></table></div></section><div class="two-col"><section class="panel"><h2>字段对照</h2><dl class="kv"><dt>姓名</dt><dd>学员姓名</dd><dt>机构编号</dt><dd>身份核对依据（样例）</dd><dt>考场 / 排次</dt><dd>使用导入表既有安排</dd></dl><p class="small muted">正式名单字段与身份依据待样例确认。导入成功不代表学员已经确认账号。</p></section><section class="panel"><h2>确认本批导入</h2><p class="small">新增或关联2行，已有1行沿用原安排。本次不会重复创建C的应考记录。</p>${!s.identity?`<p class="small" style="color:var(--warning)">请先核对第3行同名账号。</p>`:''}<div class="actions">${btn(s.roster?'查询本批导入结果':'确认本批导入','import','primary',!s.identity)}${btn('下载问题行','download-issues')}</div></section></div>`)}
function pageW03(){const s=current();return desktop(`${heading('整套试卷','本场使用固定题目版本，考过的内容不会被后续编辑覆盖。',link('W01','返回本场准备'))}<div class="two-col"><section class="panel"><h2>本场套卷检查</h2><div class="table-scroll"><table><thead><tr><th>套卷 / 版本</th><th>完整性</th><th>本场状态</th></tr></thead><tbody><tr><td><strong>17号 · v1</strong></td><td>3 / 3 科</td><td>${tag('可抽取','success')}</td></tr><tr><td><strong>18号 · v1</strong></td><td>${s.paper18?'3 / 3 科':'2 / 3 科'}</td><td>${tag(s.paper18?'完整待选用':'缺新闻播报',s.paper18?'success':'warning')}</td></tr></tbody></table></div><hr>${s.paper18?banner('18号材料已补齐。检查通过后才能选入本场。'):banner('18号缺新闻播报，暂不加入本场可抽范围。17号仍可正常使用。','warning')}<div class="actions">${btn(s.paper18?'检查并选入本场':'补充18号缺少材料','paper-fill','primary')}${btn('预览作答展示','paper-preview')}</div></section><section class="panel"><div class="panel-title"><h2>17号套卷 · 展示预览</h2>${tag('本场 v1')}</div><div class="tabs">${subjects.map((x,i)=>btn(x,`paper-tab:${i}`,i===material?'active':'')).join('')}</div><div class="paper"><h3>${subjects[material]}</h3>${question(material)}</div><p class="fine">这里核对版面。正式题材长度、分页与观看距离需要使用实际样例验证。</p></section></div>`)}
function question(q){return ["请朗读下面的文字：<br>清晨，第一缕阳光越过树梢，落在安静的小路上。风带来草木的气息，也把远处的声音轻轻送到耳边。<br>请以自然、清晰的表达，传达这段文字中的画面与情绪。","请播报下面的新闻材料：<br>近日，城市公共阅读空间向市民开放。新空间设置阅读、交流与文化展示等区域，让更多人在日常生活中接近书籍、分享知识。<br>请注意信息层次、语速与停连。","请围绕以下话题进行评述：<br><strong>当更多公共空间向年轻人开放，我们应如何参与和维护？</strong><br>可以结合观察与具体例子，表达你的观点。"] [q]}
function pageM01(){const s=current();const list=people().filter(p=>monitorFilter==='all'||(monitorFilter==='waiting'&&p.id==='A'&&s.checkin&&!s.onsiteEnded)||(monitorFilter==='unsigned'&&p.id==='A'&&!s.checkin));return phone('监考工作台',`<div class="eyebrow">第一轮 · 03考场</div><h1>签到与候考</h1><div class="panel"><div class="panel-title"><h2>本考场签到码</h2>${tag('已签到 '+(2+Number(s.checkin))+'/3')}</div><p class="small muted">由学员在本人账号扫码并确认，监考员查看签到结果。</p><div class="actions">${btn('展示签到码','qr','primary')}</div></div><section class="panel"><div class="panel-title"><h2>当前交接</h2>${tag(s.onsiteEnded?'现场已结束':s.handoff==='accepted'?'场内已接收':s.handoff==='pending'?'等待场内接收':'尚未交接',s.handoff==='accepted'?'success':'warning')}</div><div class="student-name"><span class="avatar">A</span><div><h2>示例学员A</h2><p>YF-001 · 计划排次09</p></div></div><dl class="kv"><dt>本人签到</dt><dd>${s.checkin?'已签到 · '+s.checkinAt:'尚未签到'}</dd><dt>本次题套</dt><dd>${s.draw?'17号 · v1':'尚未抽取'}</dd><dt>场内反馈</dt><dd>${s.onsiteEnded?'现场已结束，上传另行处理':s.handoff==='accepted'?'当前学员A已被录制员接收':s.handoff==='pending'?'已发送，等待录制员接收':'当前无已接收学员'}</dd></dl>${s.handoff==='idle'?`${banner(s.checkin?'签到成功只代表到场，请按现场安排核对本人后交接。':'等待学员本人扫码签到。','warning')}<div class="actions">${btn('交给场内','handoff','primary',!s.checkin||s.offline)}</div>`:s.handoff==='pending'?`<div class="actions">${btn('查询当前交接','query-handoff')}</div>`:banner(s.onsiteEnded?'A的现场考试已结束，上传和材料核对由各岗位继续处理。':'场内已接收A，等待本位现场结束。')}<p class="fine">最近同步10:24 · 本页不操作录制或成绩。</p></section><section class="panel"><h2>本考场名单</h2><label class="sr-only" for="monitor-filter">筛选签到状态</label><select id="monitor-filter"><option value="all" ${monitorFilter==='all'?'selected':''}>全部学员</option><option value="unsigned" ${monitorFilter==='unsigned'?'selected':''}>尚未签到</option><option value="waiting" ${monitorFilter==='waiting'?'selected':''}>已签到待候考</option></select><hr>${list.length?list.map(p=>`<div class="listrow"><div><strong>${p.seat} · ${p.name}</strong><p>${p.code} · ${p.id==='A'?(s.onsiteEnded?'现场已结束':s.handoff==='accepted'?'场内已接收':s.checkin?'已签到待候考':'尚未签到'):'现场已结束'}</p></div>${tag(p.id==='A'&&!s.onsiteEnded?'本位':'已结束')}</div>`).join(''):'<p class="small muted">当前筛选没有学员，切换“全部学员”继续查看。</p>'}</section>`)}
function studentState(s){return s.onsiteEnded?'现场考试已结束':s.handoff==='accepted'?'场内已接收':s.handoff==='pending'?'等待场内接收':s.checkin?'已签到，请场外等候':'尚未签到'}
function pageS00(){const s=current();return phone('我的考试',`<div class="student-name"><span class="avatar">A</span><div><h2>${s.person.name}</h2><p>${s.person.code} · ${s.person.class}</p></div></div><h1>我的考试</h1><p class="small muted">只显示本人参加的考试与已发布成绩。</p><section class="panel"><div class="eyebrow">2026年10月22日</div><h2>${esc(s.examName)}</h2><div class="pill-row">${tag('03考场')}${tag('排次09')}${tag(studentState(s),s.checkin?'success':'warning')}</div><hr><div class="actions">${link('S01','查看本场安排','primary')}${link('S02',s.published?'查看已发布成绩':'查看成绩状态')}</div></section>`)}
function pageS01(){const s=current();return phone('本场安排',`<div class="student-name"><span class="avatar">A</span><div><h2>${s.person.name}</h2><p>${s.person.code} · 本人考试安排</p></div></div><div class="hero">${shape}<div class="eyebrow">本次考试</div><h1>第一轮<br>播音模拟考</h1><p>2026年10月22日</p><div class="pill-row">${tag('03考场')}${tag('计划排次09')}</div></div><section class="panel"><h2>${studentState(s)}</h2><p class="small muted">${s.checkin?'请按工作人员引导候考或进行考试。签到成功不等于可自行入场。':'到场后使用本人账号扫描监考员出示的签到码，核对本场考场后确认签到。'}</p><div class="actions">${s.checkin?link('S04','查看本人签到结果','primary'):link('S03','扫一扫签到','primary')}${s.checkin?link('D01','查看本次抽题'):''}</div></section><section class="panel"><h2>本人成绩</h2><p class="small muted">${s.published?'本次已发布，可以查看本人三科结果。':'成绩尚未发布，老师评分不会提前向学员展示。'}</p><div class="actions">${link('S02',s.published?'查看已发布成绩':'查看成绩状态')}</div></section>`)}
function pageS03(){const s=current(),scan=params.get('scan')||'';return phone('扫码签到',`<div class="eyebrow">${s.person.name} · 本人账号</div><h1>到场签到</h1>${!scan?`<section class="panel"><div class="scan-window" aria-label="扫码取景界面示意"><span>对准监考员展示的签到码</span></div><h2>扫描考场签到码</h2><p class="small muted">扫码后先核对考试、考场和本人信息，再确认签到。</p><p class="fine">扫码画面示意，未连接摄像头。</p></section>`:scan==='wrong'?`<section class="panel"><h2>这不是你的考场</h2>${banner('扫描到02考场，系统安排为03考场。没有为你改场或签到。','error')}<dl class="kv"><dt>本人</dt><dd>${s.person.name} / ${s.person.code}</dd><dt>原安排</dt><dd>03考场 · 计划排次09</dd><dt>扫码来源</dt><dd>第一轮 / 02考场</dd></dl><div class="actions">${btn('重新扫码','scan-again')}</div></section>`:scan!=='valid'?`<section class="panel"><h2>签到码已失效</h2>${banner('请让监考员重新展示本场签到码后再扫码。当前没有新增签到。','warning')}<div class="actions">${btn('重新扫码','scan-again')}</div></section>`:`<section class="panel"><h2>${s.checkin?'本次已经签到':'核对本次签到信息'}</h2><dl class="kv"><dt>考试</dt><dd>${esc(s.examName)}</dd><dt>扫码考场</dt><dd>03考场</dd><dt>本人</dt><dd>${s.person.name} / ${s.person.code}</dd><dt>计划排次</dt><dd>09</dd></dl>${banner(s.checkin?'将显示原签到结果，不会再新增一条签到。':'确认只记录本场到场状态，入场仍由工作人员安排。')}<div class="actions">${btn(s.checkin?'查看原签到结果':'确认本人信息并签到','checkin','primary',s.offline)}</div></section>`}<div class="actions">${link('S01','返回本场安排')}</div>`)}
function pageS04(){const s=current();return phone('本人签到结果',`<section class="panel">${s.checkin?`<div class="big-status" aria-hidden="true">✓</div><h1>签到成功</h1><dl class="kv"><dt>本人</dt><dd>${s.person.name}</dd><dt>编号</dt><dd>${s.person.code}</dd><dt>考试</dt><dd>${esc(s.examName)}</dd><dt>考场 / 排次</dt><dd>03考场 / 09</dd><dt>签到时间</dt><dd>${s.checkinAt}</dd></dl>${banner(s.onsiteEnded?'本次现场考试已结束。成绩需等待机构发布。':s.handoff==='accepted'?'场内已接收，请按工作人员引导考试。':'请在场外等候，向监考员出示本结果。签到成功不代表可以自行入场。')}<div class="actions">${link('S01','查看候考与考试安排','primary')}${btn('查询本次签到结果','checkin-query')}</div>`:`<h1>本人尚未签到</h1><p>到场后请扫描本考场签到码。</p>${link('S03','进入扫码签到','primary')}`}</section>`)}
function pageD01(){const s=current();return phone('现场抽题',`${heading('本次整套试题','第一轮播音模拟考 · 示例学员A')}<section class="panel">${s.drawPending?`<h2>正在确认抽题结果</h2>${banner('请求已提交，结果尚未确认。请查询本次结果，不要再次抽题。','warning')}<div class="actions">${btn('查询本次抽题结果','draw-query','primary')}</div>`:s.draw?`<div class="eyebrow">本次已抽中</div><div class="queue-no">17 <small>号套卷</small></div><p class="muted small">本场版本 v1 · 三科使用同一整套</p>${banner('重新进入仍显示这次的17号套卷。下一轮考试另行抽取。')}<div class="listrow"><div><strong>作品朗读</strong><p>按现场安排开放材料</p></div>${tag('已分配')}</div><div class="listrow"><div><strong>新闻播报</strong></div>${tag('已分配')}</div><div class="listrow"><div><strong>话题评述</strong></div>${tag('已分配')}</div><hr><div class="actions">${btn('查询本次抽题结果','draw-query')}${link('S01','返回我的考试')}</div>`:`<h2>随机抽取一整套</h2><p class="small muted">请核对本次考试与本人信息。抽取后，本次考试的三科使用同一套题。</p>${!s.checkin?banner('请先完成本场签到。','warning'):''}<div class="actions">${btn('随机抽取一套','draw','primary',!s.checkin||s.offline)}${link('S01','返回我的考试')}</div>`}</section><p class="small muted">请按现场工作人员安排备稿和入场。</p>`)}
function pageA01(){const s=current();return phone('考场录制',`<div class="eyebrow">设备 03-01 · 03考场</div><h1>开场检查</h1><div class="panel">${video('取景预览')}<label class="device-check"><input type="checkbox" id="camera-check" ${s.device?'checked':''}><span>画面方向与构图已检查</span></label><label class="device-check"><input type="checkbox" id="audio-check" ${s.device?'checked':''}><span>收音与回放已检查</span></label><label class="device-check"><input type="checkbox" id="mirror-check" ${s.device?'checked':''}><span>大屏与手机同画面已检查</span></label><div class="actions">${btn(s.device?'重新记录设备检查':'记录设备检查','device','primary')}</div><p class="fine">需在实际设备上确认画面、声音与镜像。</p></div><section class="panel"><div class="panel-title"><h2>当前学员</h2>${tag(s.onsiteEnded?'现场已结束':s.handoff==='accepted'?'已接收':s.handoff==='pending'?'待接收':'尚未交接',s.handoff==='accepted'?'success':'warning')}</div><div class="student-name"><span class="avatar">A</span><div><h2>示例学员A</h2><p>YF-001 · 排次09 · ${s.draw?'17号套卷':'尚未抽题'}</p></div></div>${s.handoff==='accepted'?`<div class="actions">${link('A02',s.onsiteEnded?'查看本地录制结果':'进入本科准备','primary')}</div>`:`<p class="small muted">收到监考交接后，核对本人、题套和设备，再确认接收。</p><div class="actions">${btn('确认当前学员并接收','accept','primary',!s.device||!s.draw||s.handoff!=='pending'||s.offline)}</div>${!s.device?'<p class="fine">请先完成设备检查。</p>':''}${s.handoff!=='pending'?'<p class="fine">当前没有待接收交接，请联系监考员。</p>':''}`}</section><div class="panel"><div class="listrow"><div><strong>本机待上传</strong><p>${s.upload.filter(x=>x==='failed').length}份上传失败 · 文件保留在原学员名下</p></div>${link('A03','查看队列','link')}</div></div>`)}
function pageA02(){const s=current(),q=s.subject;let body='',controls='',extra='';if(s.handoff!=='accepted'||!s.draw){body=`<section class="panel empty"><strong>请先确认当前学员</strong><p>完成设备检查、抽题与场内接收后，再进入科目准备。</p>${link('A01','返回设备与当前人','primary')}</section>`}else if(s.stage==='recording'){extra=' recording';body=`<div class="record-question"><div class="question-number">${q+1} / 3　${subjects[q]} · 17号套卷</div><h1>${subjects[q]}</h1><p>${question(q)}</p></div><aside class="record-aside"><div class="video"><div class="person" aria-hidden="true"></div><small>画面示意</small></div><p class="fine">请保持画面与收音稳定</p></aside>`;controls=`<div class="record-status"><div><div class="recording-label">正在录制</div><span class="small muted">本科目进行中</span></div><div class="timer" id="timer" aria-label="剩余作答时间">02:00</div></div><div class="actions">${btn('异常结束','interrupt','danger')}${btn('结束本科并保存','finish','primary')}</div>`}else if(s.stage==='saving'){body=`<div class="panel empty"><strong>正在保存本科视频</strong><p>请勿退出、换人或切换考场。</p><div class="progress"><i style="width:65%"></i></div></div>`;controls=tag('正在封装文件','warning')}else if(s.abnormal?.[q]){body=`<section class="panel"><h1>异常片段已保留</h1>${banner('原学员A / '+subjects[q]+' / 17号-v1。该片段不是完整录制，不能直接作为评分材料。','warning')}<p>请联系负责人处理补录决定，不能直接恢复倒计时继续。</p>${link('A03','查看原文件记录')}</section>`;controls=tag('等待负责人处理','warning')}else if(s.local[q]){body=`<div class="two-col"><div class="panel">${video(`${subjects[q]} · 本机文件 A-${q+1}`)}</div><section class="panel"><div class="eyebrow">本科录制结果</div><h1>本地已保存</h1><dl class="kv"><dt>归属</dt><dd>示例学员A / ${subjects[q]}</dd><dt>文件</dt><dd>A-${q+1} · 17号-v1</dd><dt>上传</dt><dd>${uploadText(s.upload[q])}</dd></dl>${banner('先检查本机结果。后台收到与材料核对状态会另外更新。')}<div class="actions">${btn('检查本科结果并加入上传','verify-local','primary',s.upload[q]!=='none')}${s.upload[q]!=='none'?link('A03','查看上传队列'):''}</div></section></div>`;controls=`<span class="small">${q+1}/3科 · 本地已保存</span><div class="actions">${q<2?btn('进入下一科','next-subject','primary',s.upload[q]==='none'):btn(s.onsiteEnded?'本位现场已结束':'结束本位现场考试','end-candidate','primary',s.upload[q]==='none'||s.onsiteEnded)}${link('A03','手机视频队列')}</div>`}else{body=`<div class="two-col"><section class="record-question"><div class="question-number">本科准备 · ${q+1} / 3</div><h1>${subjects[q]}</h1><div class="paper">${question(q)}</div><p class="fine">17号套卷 · 本场内容版本 v1</p></section><section class="panel"><h2>确认后开始本科</h2>${video('准备画面')}<dl class="kv"><dt>当前学员</dt><dd>示例学员A / YF-001</dd><dt>题套</dt><dd>17号 · ${subjects[q]}</dd><dt>设备</dt><dd>03-01 · 设备检查已记录</dd></dl></section></div>`;controls=`<div class="record-status"><div class="timer">02:00</div><span class="small muted">本科作答时长</span></div><div class="actions">${btn('返回当前人','back-recorder')}${btn('开始本科录制','start-record','primary')}</div>`}return `<div class="record-layout${extra}"><header class="record-header"><img src="assets/yifeng-logo.png" alt="艺风传媒"><div class="record-meta">第一轮播音模拟考 · 03考场<br><strong>${s.stage==='recording'?subjects[q]+' · 17号套卷':'示例学员A · '+subjects[q]}</strong></div>${tag(s.stage==='recording'?'录制进行中':'手机与大屏同画面',s.stage==='recording'?'error':'')}</header><main id="main" class="record-body" tabindex="-1">${feedback?banner(esc(feedback),feedbackType):''}${body}</main>${controls?`<footer class="record-controls">${controls}</footer>`:''}</div>`}
function uploadText(v){return {none:'尚未加入上传',queued:'待上传',uploading:'正在上传',failed:'上传失败 · 本机文件保留',received:'后台已收到，待核对'}[v]||v}
function pageA03(){const s=current();return phone('手机视频队列',`<div class="eyebrow">设备 03-01 · 本机文件</div><h1>保存与上传</h1><div class="three-col" style="grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:20px"><div class="stat" style="padding:12px"><small>本地保存</small><strong>${s.local.filter(Boolean).length}</strong></div><div class="stat" style="padding:12px"><small>后台收到</small><strong>${s.upload.filter(x=>x==='received').length}</strong></div><div class="stat" style="padding:12px"><small>核对通过</small><strong>${s.checked.filter(Boolean).length}</strong></div></div>${s.local.some(Boolean)?subjects.map((name,q)=>s.local[q]?`<section class="panel"><div class="panel-title"><h2>${name}</h2>${tag(s.checked[q]?'核对通过':s.upload[q]==='received'?'后台已收到':s.upload[q]==='failed'?'上传失败':'待传',s.upload[q]==='failed'?'error':s.checked[q]?'success':'warning')}</div><p class="small">示例学员A · YF-001<br>第一轮 / 03考场 / 17号-v1<br>${s.abnormal?.[q]?'异常片段 · 等待负责人处理<br>':''}原文件 A-${q+1} · ${q+1===1?'128':'96'}MB</p><p class="small muted">${uploadText(s.upload[q])}</p>${s.upload[q]==='failed'?banner('上传失败不会改变文件归属，也不需要直接重录。请恢复连接后重试原文件。','error'):''}${s.upload[q]!=='received'?`<div class="actions">${btn(s.upload[q]==='failed'?'重试原文件上传':'上传原文件',`upload:${q}`,'primary',s.offline||s.upload[q]==='uploading'||s.abnormal?.[q])}</div>`:banner(s.checked[q]?'后台已核对通过，本机文件暂时保留。':'后台已收到，等待材料负责人核对。')}</section>`:'').join(''):`<div class="panel empty"><strong>本机没有待传文件</strong><p>录制并保存本科视频后，可在这里查看归属与上传状态。</p>${link('A01','返回设备与当前人')}</div>`}<div class="actions">${link('A02','返回当前科目')}${link('W04','查看后台材料')}</div>`)}
function pageW04(){const s=current(),q=material;let count=s.upload.filter(x=>x==='received').length+6;return desktop(`${heading('视频与材料核对','先按应有名单找齐，再确认评分使用的材料版本。',btn('检查本科目评卷条件','open-subject','primary'))}<div class="three-col" style="margin-bottom:20px"><div class="stat"><small>应有视频</small><strong>9</strong><small>3名学员 × 3科</small></div><div class="stat"><small>后台已收到</small><strong>${count} <small>/ 9</small></strong></div><div class="stat"><small>已核对通过</small><strong>${s.checked.filter(Boolean).length+6} <small>/ 9</small></strong></div></div><div class="tabs">${subjects.map((x,i)=>btn(x,`material-tab:${i}`,i===q?'active':'')).join('')}</div><div class="two-col"><section class="panel"><div class="panel-title"><h2>${subjects[q]} · 按名单检查</h2>${tag(s.opened[q]?'已开放评卷':'尚未开放',s.opened[q]?'success':'warning')}</div><div class="table-scroll"><table><thead><tr><th>学员 / 应考记录</th><th>材料状态</th><th>有效版本</th></tr></thead><tbody>${people().map(p=>`<tr class="${p.id==='A'?'row-highlight':''}"><td>${p.name}<small>${p.code} · 03考场</small></td><td>${p.id!=='A'?tag('核对通过','success'):tag(s.checked[q]?'核对通过':s.upload[q]==='received'?'收到待核对':'缺视频',s.checked[q]?'success':'warning')}</td><td>${p.id!=='A'||s.checked[q]?'v1':'尚未选定'}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>示例学员A · ${subjects[q]}</h2>${s.upload[q]==='received'?`${video('A-'+(q+1)+' · 本场视频 v1')}<dl class="kv"><dt>来源设备</dt><dd>03-01 / 工作人员甲</dd><dt>归属</dt><dd>A / 第一轮 / ${subjects[q]}</dd><dt>套卷版本</dt><dd>17号-v1</dd></dl><div class="actions">${btn(s.checked[q]?'已确认评分用视频 v1':'确认评分用视频 v1','confirm-video','primary',s.checked[q])}</div>`:`${banner('后台尚未收到A的本科视频。请联系录制员检查03-01原文件。','warning')}<dl class="kv"><dt>负责人</dt><dd>工作人员甲</dd><dt>本机状态</dt><dd>${s.local[q]?uploadText(s.upload[q]):'尚未本地保存'}</dd></dl>${link('A03','查看原设备上传队列')}`}</section></div>`)}
function pageW05(){const s=current(),q=s.scoreSub;return desktop(`${heading('我的评卷任务',actor.name+' · 本人负责的3科，各科全部3名学员')}<div class="three-col">${subjects.map((name,i)=>`<section class="taskcard"><div class="icon">▷</div>${tag(s.opened[i]?'可评卷':'材料未开放',s.opened[i]?'success':'warning')}<h2>${name}</h2><p>本人已保存 ${taskStatus(i)}/3 · 全部学员由本人逐一评阅</p><div class="progress"><i style="width:${taskStatus(i)/3*100}%"></i></div>${btn(taskStatus(i)===3?'查看本人已评分':'继续本人未评',`grade-subject:${i}`,'primary',!s.opened[i])}</section>`).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-title"><h2>我已保存的评分</h2>${tag('仅本人')}</div><div class="tabs">${subjects.map((n,i)=>btn(n,`grade-list:${i}`,i===q?'active':'')).join('')}</div><div class="table-scroll"><table><thead><tr><th>本科应考任务</th><th>本人分数</th><th>保存状态</th><th>操作</th></tr></thead><tbody>${people().map(p=>{const v=s.scores[`${q}-${s.teacher}-${p.id}`];return `<tr><td>应考 ${p.code}</td><td class="cell-number">${v??'尚未评分'}</td><td>${tag(Number.isFinite(v)?'已保存':'待评分',Number.isFinite(v)?'success':'warning')}</td><td>${btn(Number.isFinite(v)?'查看本人评分':'开始评分',`grade-person:${p.id}`,'',!s.opened[q])}</td></tr>`}).join('')}</tbody></table></div><p class="fine">本页没有其他老师的原始分、平均分或排名。</p></section>`)}
function pageW06(){const s=current(),q=s.scoreSub,t=s.teacher,key=scoreKey(s),draft=s.drafts[key],saved=s.scores[key],value=draft!==undefined?draft:saved??'',dirty=draft!==undefined&&String(draft)!==String(saved??'');return desktop(`${heading(subjects[q]+' · 看片评分','评卷老师'+(t+1)+' · 本科全部3名学员 · 已保存 '+taskStatus(q)+'/3',link('W05','返回我的任务'))}<div class="panel" style="padding:14px 18px"><div class="actions"><div><label class="sr-only" for="grade-subject">科目</label><select id="grade-subject">${subjects.map((n,i)=>`<option value="${i}" ${i===q?'selected':''}>${n}</option>`).join('')}</select></div><span class="tag">评卷老师${t+1} · 本人任务</span><div><label class="sr-only" for="grade-student">学员任务</label><select id="grade-student">${people().map(p=>`<option value="${p.id}" ${p.id===s.student?'selected':''}>应考 ${p.code}${Number.isFinite(s.scores[`${q}-${t}-${p.id}`])?' · 已保存':' · 待评'}</option>`).join('')}</select></div></div></div>${!s.opened[q]?banner('本科目尚未开放评卷。先完成材料核对，再继续评分。','warning'):''}<div class="two-col"><section><div class="panel"><div class="panel-title"><h2>应考 ${people().find(p=>p.id===s.student).code}</h2>${tag('评分用视频 v1')}</div>${video('17号-v1 · '+subjects[q])}<div class="actions">${btn('报告视频问题','report-video','link')}</div></div><section class="panel"><h2>本次试题</h2><div class="paper">${question(q)}</div></section></section><section class="panel score-form"><h2>本科评分</h2><div class="paper"><strong>评分参考</strong><p class="small muted">内容表达、语言清晰度与呈现状态。具体标准以正式评分规则为准。</p></div><hr><label for="score">分数 <span class="muted">/ 100</span></label><input id="score" class="score-input" type="number" min="0" max="100" step="0.01" value="${esc(value)}" aria-describedby="score-help score-status" ${!s.opened[q]?'disabled':''}><div id="score-help" class="field-hint">0–100，可保留2位小数（演示规则）</div><div id="score-status" class="save-status ${!dirty&&Number.isFinite(saved)?'saved':''}" role="status">${dirty?'有未保存的输入':Number.isFinite(saved)?'✓ 已保存 '+saved+'分 · 视频 v1':'尚未保存评分'}</div>${s.scoreIssue[key]?banner('视频问题已登记，任务保留待处理。','warning'):''}<div class="actions">${btn('只保存','save-score','',!s.opened[q]||loading)}${btn(loading?'正在保存…':'保存并下一份','save-next','primary',!s.opened[q]||loading)}</div><p class="fine">确认保存成功后才推进。保存失败会保留当前输入与视频。</p></section></div>`)}
function missingRows(){const s=current();let a=[];for(let q=0;q<3;q++)for(let t=0;t<2;t++)for(const p of people())if(!Number.isFinite(s.scores[`${q}-${t}-${p.id}`]))a.push({q,t,p});return a}
function pageW07(){const s=current(),missing=missingRows();return desktop(`${heading('成绩核对','按科核对两位老师的原始分。缺评不会缩小平均分的分母。',btn('导出核对表','export')+btn('检查发布条件','check-publish','primary'))}${s.published?banner(s.resultChanged?'已发布v'+s.publishVersion+'，当前评分已有更改。下表为最新评分，学员仍查看原发布版本；核对后可另发更正版本。':'本场成绩已发布 · v'+s.publishVersion+'。学员本人可以查看该版本。',s.resultChanged?'warning':''):missing.length?banner('还有'+missing.length+'份评分未保存。受影响科目不形成最终平均分，不能发布最终结果。','warning'):banner('本科目评分已齐备。请继续核对材料、字段和发布预览。')}<section class="panel"><div class="panel-title"><h2>按科平均分</h2>${tag(s.published?'已发布':'尚未发布',s.published?'success':'warning')}</div><div class="table-scroll"><table><thead><tr><th>学员</th>${subjects.map(x=>`<th>${x}</th>`).join('')}<th>结果</th></tr></thead><tbody>${people().map(p=>`<tr><td>${p.name}<small>${p.code}</small></td>${subjects.map((x,q)=>`<td class="cell-number">${average(q,p.id)??tag('缺评，未合分','warning')}<small>${[0,1].map(t=>'老师'+(t+1)+': '+(s.scores[`${q}-${t}-${p.id}`]??'未保存')).join(' / ')}</small></td>`).join('')}<td>${tag(subjects.every((x,q)=>average(q,p.id))?'本科平均已齐':'待补评',subjects.every((x,q)=>average(q,p.id))?'success':'warning')}</td></tr>`).join('')}</tbody></table></div><p class="fine">只展示按科平均；跨科总分、小数和例外发布规则待确认，不在本稿合成总分。</p></section>${missing.length?`<section class="panel"><h2>缺评清单</h2>${missing.map(m=>`<div class="listrow"><div><strong>${m.p.name} · ${subjects[m.q]}</strong><p>评卷老师${m.t+1} · 应评全部3名学员</p></div>${btn('定位评分任务',`missing:${m.q}:${m.t}:${m.p.id}`,'link')}</div>`).join('')}</section>`:`<section class="panel"><h2>继续核对发布内容</h2><p class="small muted">导出核对文件与对学员发布是两个独立动作。</p>${link('W08','查看发布预览 →','primary')}</section>`}`)}
function pageW08(){const s=current(),ready=adminReady();return desktop(`${heading('发布预览','请核对本次发布的人数、可见字段与结果版本。',link('W07','返回成绩核对'))}${!ready?banner('发布条件未满足：评分未齐或材料未开放。先处理缺评与材料，再重新核对。','warning'):''}<div class="two-col"><section class="panel"><h2>学员将看到</h2><div class="report-title"><img src="assets/yifeng-logo.png" alt="艺风传媒"><h2 style="margin-top:20px">第一轮播音模拟考</h2><p class="small muted">示例学员A · 本人成绩</p></div><div class="score-grid">${subjects.map((name,q)=>`<div><span class="small">${name}</span><strong>${average(q)||'待补评'}</strong><small class="muted">本科平均</small></div>`).join('')}</div><p class="fine">不包含其他学员、老师原始评分和视频下载入口。</p></section><aside><section class="panel"><h2>本次发布范围</h2><dl class="kv"><dt>考试</dt><dd>第一轮播音模拟考</dd><dt>人数</dt><dd>3名学员 · 本人可见</dd><dt>可见字段</dt><dd>考试名称、三科平均分、更新时间</dd><dt>评分版本</dt><dd>修订 ${s.scoreRev}</dd><dt>发布版本</dt><dd>${s.published&&!s.resultChanged?'已发布 v'+s.publishVersion:'将发布 v'+(s.publishVersion+1)+(s.published?'（当前学生看v'+s.publishVersion+'）':'')}</dd></dl><hr><div class="actions">${btn(s.published&&!s.resultChanged?'本次版本已发布':s.published?'发布更正版本':'发布本次结果','publish-confirm','primary',!ready||(s.published&&!s.resultChanged)||s.offline)}</div><p class="fine">发布需要独立确认。核对表导出不会发布。</p></section></aside></div>`)}
function pageS02(){const s=current(),pub=s.publication;return phone('我的成绩',`<div class="eyebrow">${s.person.name} · 仅本人结果</div><h1>${esc(pub?.examName||s.examName)}</h1><p class="muted small">2026年10月22日 · 03考场</p>${s.published&&pub?`<section class="panel"><div class="big-status">✓</div><h2>本次成绩已发布</h2><p class="small muted">发布版本 v${pub.version}<br>更新时间：${pub.publishedAt}</p><div class="score-grid">${subjects.map((n,q)=>`<div><span class="small">${n}</span><strong>${pub.result[q]}</strong><small class="muted">本科平均分</small></div>`).join('')}</div><p class="fine">仅显示本人已发布版本，不展示老师原始分和其他学员。后台仍在编辑的分数不会改变此版本。</p></section>`:`<section class="panel empty"><div class="big-status" style="margin:0 auto 20px">◷</div><strong>本次成绩尚未发布</strong><p>老师已保存的评分需要机构核对并发布后，才会向本人显示。</p>${btn('刷新发布状态','refresh-results')}</section>`}<div class="actions">${link('S01','查看本场安排')}${link('S00','返回我的考试')}</div>`)}
function pageW10(){const s=current();let rows=[];for(let q=0;q<3;q++)for(let t=0;t<2;t++){if(adminSubject!=='all'&&+adminSubject!==q)continue;if(adminTeacher!=='all'&&+adminTeacher!==t)continue;const count=people().filter(p=>Number.isFinite(s.scores[`${q}-${t}-${p.id}`])).length;rows.push({q,t,count})}return desktop(`${heading('全场评卷概览','管理员查看全部老师的分科任务与原始分，不代替老师录分。',link('W07','进入成绩核对','primary'))}<div class="three-col" style="margin-bottom:20px"><div class="stat"><small>应评任务</small><strong>18</strong><small>3科 × 2位老师 × 全部3人</small></div><div class="stat"><small>评分已保存</small><strong>${Object.values(s.scores).filter(Number.isFinite).length}</strong></div><div class="stat"><small>缺评</small><strong>${18-Object.values(s.scores).filter(Number.isFinite).length}</strong></div></div><section class="panel"><div class="actions"><div><label for="admin-subject">科目</label><select id="admin-subject"><option value="all">全部科目</option>${subjects.map((n,i)=>`<option value="${i}" ${String(i)===adminSubject?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="admin-teacher">老师</label><select id="admin-teacher"><option value="all">全部老师</option>${[0,1].map(t=>`<option value="${t}" ${String(t)===adminTeacher?'selected':''}>评卷老师${t+1}</option>`).join('')}</select></div></div><hr><div class="table-scroll"><table><thead><tr><th>科目</th><th>老师</th><th>负责学员</th><th>已保存</th><th>缺评</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${subjects[r.q]}</td><td>评卷老师${r.t+1}</td><td>全部3人</td><td>${r.count} / 3</td><td>${r.count===3?tag('已齐','success'):tag((3-r.count)+'份待评','warning')}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>全体原始评分 · 只读核对</h2><div class="table-scroll"><table><thead><tr><th>学员</th><th>科目</th><th>评卷老师1</th><th>评卷老师2</th><th>本科平均</th></tr></thead><tbody>${people().flatMap(p=>subjects.map((n,q)=>{if(adminSubject!=='all'&&+adminSubject!==q)return '';return `<tr><td>${p.name}<small>${p.code}</small></td><td>${n}</td><td>${s.scores[`${q}-0-${p.id}`]??tag('缺评','warning')}</td><td>${s.scores[`${q}-1-${p.id}`]??tag('缺评','warning')}</td><td>${average(q,p.id)??'未合分'}</td></tr>`})).join('')}</tbody></table></div><p class="fine">更正由原评分老师按权限处理。管理员只核对进度与结果，不在本页直接填分。</p></section>`)}
function pageW09(){const s=current();return desktop(`${heading('账号与负责范围','同一人可以兼岗，每一项工作都限定到考试、考场或科目。')}<div class="two-col"><section class="panel"><div class="panel-title"><h2>工作人员甲</h2>${tag(s.accountActive?'账号可用':'已停用',s.accountActive?'success':'warning')}</div><dl class="kv"><dt>账号编号</dt><dd>STAFF-001</dd><dt>当前范围</dt><dd>${esc(s.scope)}</dd><dt>授权版本</dt><dd>v${s.accountRevision}</dd></dl><hr><h3>岗位</h3><label class="device-check"><input id="role-monitor" type="checkbox" ${s.roleMonitor?'checked':''}><span>监考 · 签到、候考与交接</span></label><label class="device-check"><input id="role-record" type="checkbox" ${s.roleRecord?'checked':''}><span>录制 · 本场设备与当前学员</span></label><div class="field"><label for="scope-select">考试与考场范围</label><select id="scope-select"><option ${s.scope==='第一轮 / 03考场'?'selected':''}>第一轮 / 03考场</option><option ${s.scope==='第一轮 / 02考场'?'selected':''}>第一轮 / 02考场</option></select></div><hr><div class="actions">${btn('预览并保存调整','preview-account','primary')}${btn('停用账号','disable-account','danger')}</div></section><aside><section class="panel"><h2>待办与移交</h2><div class="listrow"><div><strong>场内当前学员</strong><p>${s.handoff==='accepted'&&!s.onsiteEnded?'示例学员A · 尚未现场结束':'当前无未结束学员'}</p></div>${tag(s.handoff==='accepted'&&!s.onsiteEnded?'需移交':'无占用',s.handoff==='accepted'&&!s.onsiteEnded?'warning':'')}</div><div class="listrow"><div><strong>本机待上传文件</strong><p>${s.upload.filter(x=>x!=='received'&&x!=='none').length}份待处理</p></div>${link('A03','查看 →','link')}</div><p class="fine">撤岗不会立即删除离线设备上的文件。未完成工作需有接手人。</p></section><section class="panel"><h2>敏感动作单独授权</h2><p class="small muted">当前岗位不包含重抽、有效视频替换或成绩更正决定权。不能只凭“管理员”标签决定业务例外。</p></section></aside></div>`)}
function render(){const s=current();if(!RolePolicy.canOpen(actorId,screen)||(s.permission&&screen!==actor.home)||(['M01','A01','A02','A03'].includes(screen)&&(!s.accountActive||s.scope!=='第一轮 / 03考场'||(screen==='M01'?!s.roleMonitor:!s.roleRecord)))){root.innerHTML=desktop(`<div class="panel permission-state"><div class="icon">◇</div><h1>当前账号无此任务权限</h1><p class="muted">请回到我的工作，选择负责范围内的任务；如有疑问联系本场负责人。</p>${btn('回到可用任务','permission-back','primary')}</div>`);return}const pages={U01:pageU01,W01:pageW01,W02:pageW02,W03:pageW03,M01:pageM01,S01:pageS01,D01:pageD01,A01:pageA01,A02:pageA02,A03:pageA03,W04:pageW04,W05:pageW05,W06:pageW06,W07:pageW07,W08:pageW08,S02:pageS02,W09:pageW09,W10:pageW10,S00:pageS00,S03:pageS03,S04:pageS04};root.innerHTML=pages[screen]();document.title='艺风 · '+Catalog.find(x=>x.id===screen).title;updateTimer()}
async function upload(q){const s=current();if(s.offline)return note('当前离线，原文件仍保留。连接恢复后重试。','warning');mutate(x=>x.upload[q]='uploading');setTimeout(()=>{mutate(x=>x.upload[q]=x.networkFail?'failed':'received');note(current().networkFail?'上传失败。A的本科原文件保留，请重试原文件。':'后台已收到A的本科视频，仍需材料核对。',current().networkFail?'error':'info')},600)}
function exportCSV(name,rows){const blob=new Blob(['\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function dirtyScore(){const s=current(),k=scoreKey(s);return s.drafts[k]!==undefined&&String(s.drafts[k])!==String(s.scores[k]??'')}
function saveScore(next){const s=current(),k=scoreKey(s),raw=$('#score')?.value??s.drafts[k];if(raw===''||!Number.isFinite(Number(raw))||Number(raw)<0||Number(raw)>100||!/^(\d+)(\.\d{1,2})?$/.test(String(raw))){note('请填写0–100之间的分数，最多保留2位小数。','error');$('#score')?.focus();return}inputChange=true;mutate(x=>x.drafts[k]=String(raw));inputChange=false;loading=true;note('正在保存评分，请稍候。');setTimeout(()=>{loading=false;if(current().saveFail||current().offline){note('评分保存失败，当前输入已保留。恢复连接后请重试，当前任务没有推进。','error');return}mutate(x=>{x.scores[k]=Number(raw);delete x.drafts[k];x.scoreRev++;x.reviewRev=0;if(x.published)x.resultChanged=true;if(next){const p=people().find(p=>!Number.isFinite(x.scores[`${x.scoreSub}-${x.teacher}-${p.id}`]));if(p)x.student=p.id;}});note(next?'评分已保存。本科还有未评时已定位下一份；全部已评时保留当前结果。':'评分已保存 · 视频 v1。','info')},550)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,s=current();feedback='';if(!RolePolicy.canOpen(actorId,screen)||!RolePolicy.actionAllowed(actorId,a)){if(a==='permission-back'){go(actor.home);return}return note('当前身份无权执行这个操作。','warning')}if(a.startsWith('post:')){const target=a.split(':')[1];if((target==='invigilator'&&s.roleMonitor)||(target==='recorder'&&s.roleRecord)){if(s.stage==='recording')return note('录制进行中不能切换岗位。','warning');const q=new URLSearchParams({screen:RolePolicy.get(target).home,as:target});if(YF.fixture)q.set('fixture',YF.fixture);location.href='page.html?'+q}return}if(a.startsWith('edit-draft:')){location.href=pageURL('W01',{draft:a.slice(11)});return}if(a.startsWith('go:')){if(screen==='W06'&&dirtyScore()){modal('当前评分尚未保存','<p>分数输入已在本机保留。返回列表不会提交评分。</p>','保留输入并返回',a.replace('go:','leave:'));return}go(a.slice(3));return}if(a.startsWith('leave:')){closeModal();go(a.slice(6));return}if(a.startsWith('paper-tab:')){material=+a.split(':')[1];render();return}if(a.startsWith('material-tab:')){material=+a.split(':')[1];mutate(x=>x.materialSub=material);return}if(a.startsWith('upload:')){upload(+a.split(':')[1]);return}if(a.startsWith('grade-list:')){mutate(x=>x.scoreSub=+a.split(':')[1]);return}if(a.startsWith('grade-person:')){mutate(x=>x.student=a.split(':')[1]);go('W06');return}if(a.startsWith('grade-subject:')){mutate(x=>{x.scoreSub=+a.split(':')[1];const p=people().find(p=>!Number.isFinite(x.scores[`${x.scoreSub}-${x.teacher}-${p.id}`]));x.student=p?.id||'A'});go('W06');return}if(a.startsWith('missing:')){const [,q,t,p]=a.split(':');modal('缺评任务定位',`<dl class="kv"><dt>学员</dt><dd>${people().find(x=>x.id===p).name}</dd><dt>科目</dt><dd>${subjects[+q]}</dd><dt>应评分老师</dt><dd>评卷老师${+t+1}</dd></dl><p class="small muted">请由该老师进入本科任务完成评分。负责人不能代为录分，当前未改变任何评分身份或分数。</p>`,'知道了','close-dialog');return}
switch(a){
case'switch-post':if(s.stage==='recording')return note('当前正在录制，请先保存或处理异常后再切换岗位。','warning');modal('切换已授权岗位',`<p>工作人员甲可在03考场兼任监考与录制。切换后只显示当前岗位的任务与操作。</p><div class="actions">${btn('进入监考工作区','post:invigilator')}${btn('进入录制工作区','post:recorder')}</div>`,'取消','close-dialog');break;case'new-exam':modal('新建考试草稿',`<div class="form-grid">${field('new-exam-name','考试名称','第二轮播音模拟考')}${field('new-exam-date','考试日期','2026-10-29','date')}</div><p class="fine">建立独立草稿；不复制当前考试的签到、题目抽取、视频或成绩。</p>`,'创建草稿','create-exam-draft');break;
case'create-exam-draft':{const name=$('#new-exam-name').value.trim(),date=$('#new-exam-date').value;if(!name||!date)return;const id='EX-D'+String((s.examDrafts||[]).length+1).padStart(3,'0');closeModal();mutate(x=>{x.examDrafts=x.examDrafts||[];x.examDrafts.push({id,name,date,room:'03考场',monitor:'',recorder:'',revision:1,copied:false})});location.href=pageURL('W01',{draft:id});break}
case'save-exam-draft':{const name=$('#draft-name').value.trim(),date=$('#draft-date').value,room=$('#draft-room').value.trim(),monitor=$('#draft-monitor').value.trim(),recorder=$('#draft-recorder').value.trim();if(!name||!date||!room)return note('请填写考试名称、日期和考场。','warning');mutate(x=>{const d=x.examDrafts.find(d=>d.id===draftId);Object.assign(d,{name,date,room,monitor,recorder,revision:d.revision+1})});note('新考试草稿已保存，未改变第一轮执行记录。');break}
case'draft-copy':modal('参考本场配置','<p>将参考三科、03考场、工作人员甲的监考与录制岗位。</p><p>不复制名单、签到、抽题、视频、评分或发布状态；新场次重新核对。</p>','确认参考配置','draft-copy-confirm');break;
case'draft-copy-confirm':closeModal();mutate(x=>{const d=x.examDrafts.find(d=>d.id===draftId);Object.assign(d,{room:'03考场',monitor:'工作人员甲',recorder:'工作人员甲',copied:true,revision:d.revision+1})});note('已参考科目与人员配置，旧执行状态未复制。');break;
case'clear-filter':role='all';render();break;case'save-prep':{const name=$('#exam-name').value.trim(),date=$('#exam-date').value;if(!name||!date)return note('请填写考试名称和日期。','error');const label=$('#prep-save');label.textContent='正在保存…';setTimeout(()=>{mutate(x=>{x.examName=name;x.date=date;x.prepared=true});note('草稿已保存 · 本场配置 v1。准备缺项仍需逐项核对。')},450);break}case'check-prep':{const issues=[!s.roster&&'名单身份',!s.paper18&&'18号缺科（该套已排除）',!s.assigned&&'录制员安排'].filter(Boolean);mutate(x=>x.prepared=issues.length===0);note(issues.length?'检查发现：'+issues.join('、')+'。请从清单进入处理。':'配置检查通过。仍需在现场确认设备，不会自动开始录制。',issues.length?'warning':'info');break}case'copy-config':modal('参考上一轮配置','<p>将参考：3个科目、03考场、工作人员岗位。</p><p>本场日期、名单需重新核对；上轮签到、抽题、视频、评分和成绩不复制。</p>','应用参考配置','copy-confirm');break;case'copy-confirm':closeModal();note('已应用科目与考场参考。未带入任何上一轮执行结果，请核对本场名单与日期。');break;
case'identity':modal('核对第3行 · 同名账号',`<p class="small muted">不能只凭姓名关联。请对照机构编号与班级等身份依据。</p><label class="device-check"><input type="radio" name="identity" value="YF-002" checked><span>示例学员B · YF-002<br><small>示例二班 · 与原表编号一致</small></span></label><label class="device-check"><input type="radio" name="identity" value="YF-022"><span>示例学员B · YF-022<br><small>示例四班 · 编号不一致</small></span></label>`,'确认关联','identity-confirm');break;case'identity-confirm':{const v=document.querySelector('input[name=identity]:checked')?.value;if(v!=='YF-002')return note('选择的编号与原表不一致，请重新核对，不自动合并。','error');closeModal();mutate(x=>x.identity=true);note('第3行已关联YF-002。请继续确认本批导入。');break}case'import':if(s.offline)return note('连接已断开，批次IMP-001预览已保留。','warning');mutate(x=>x.roster=true);note('本批导入成功 · IMP-001。C沿用已有安排，没有重复应考记录。');break;case'download-issues':exportCSV('名单问题行-IMP-001.csv',[['原表行','姓名','问题'],['3','示例学员B',s.identity?'已核对YF-002':'两个同名账号，待核对']]);note('问题行文件已生成。导出不改变导入状态。');break;
case'paper-fill':if(s.paper18){mutate(x=>x.papersSelected=true);note('完整套卷检查通过。18号可选入本场；A已抽中的17号-v1不改变。')}else modal('补充18号新闻播报','<p>使用本地虚构材料填入18号新闻播报，随后重新检查整套完整性。</p>','填入并检查','paper-confirm');break;case'paper-confirm':closeModal();mutate(x=>x.paper18=true);note('18号三科已完整。请核对展示后选入本场。');break;case'paper-preview':modal('17号试题展示预览',`<div class="paper">${question(material)}</div><p class="fine">此处只核对材料排版，不提供现场录制操作。</p>`,'关闭','close-dialog');break;
case'qr':{let cells='';for(let y=0;y<25;y++)for(let x=0;x<25;x++){let v=((x*13+y*7+x*y)%11)<5;for(const [a,b]of [[0,0],[18,0],[0,18]])if(x>=a&&x<a+7&&y>=b&&y<b+7){let dx=x-a,dy=y-b;v=dx===0||dx===6||dy===0||dy===6||(dx>=2&&dx<=4&&dy>=2&&dy<=4)}cells+=`<i class="${v?'':'blank'}"></i>`}modal('03考场 · 签到码',`<p class="small muted">第一轮播音模拟考 · 只用于本场签到</p><div class="qr" aria-label="签到码图形示意，非实际二维码">${cells}</div><p class="small muted" style="text-align:center">图形示意 · 学员使用本人账号扫描此码</p>`,'关闭签到码','close-dialog');break}case'checkin':if(s.offline)return;if(screen!=='S03'||params.get('scan')!=='valid')return note('请扫描有效的03考场签到码后再确认。','warning');mutate(x=>{if(!x.checkin){x.checkin=true;x.checkinAt='10:24';x.checkinCount=(x.checkinCount||0)+1}});go('S04');break;case'scan-again':location.href=pageURL('S03');break;case'checkin-query':note('本次签到已确认，重复查询不会新增记录。');break;case'draw':mutate(x=>{x.draw=17;x.drawPending=true});break;case'draw-query':mutate(x=>x.drawPending=false);note('已查询本次记录：17号-v1。没有重新抽取。');break;case'handoff':modal('交给场内 · 示例学员A','<p>第一轮 / 03考场 / 排次09。</p><p>核对本人和现场安排后发出交接；仍需录制员确认接收。</p>','发出交接','handoff-confirm');break;case'handoff-confirm':closeModal();mutate(x=>x.handoff='pending');note('已发出交接，等待场内接收。当前不能继续推送下一位。');break;case'query-handoff':note(s.handoff==='accepted'?'场内已接收A。':'交接仍待录制员接收，当前学员仍为A。');break;
case'device':if(!$('#camera-check').checked||!$('#audio-check').checked||!$('#mirror-check').checked)return note('请先逐项确认画面、收音和同屏检查。','warning');mutate(x=>x.device=true);note('设备检查已记录。请再核对当前人和题套。');break;case'accept':mutate(x=>x.handoff='accepted');note('当前学员A已接收。监考端可看到接收结果。');break;case'back-recorder':go('A01');break;case'start-record':mutate(x=>{x.stage='recording';x.started=Date.now()});break;case'finish':mutate(x=>x.stage='saving');setTimeout(()=>mutate(x=>{x.local[x.subject]=true;x.stage='saved'}),800);break;case'verify-local':mutate(x=>x.upload[x.subject]='queued');note('本科本机检查已记录，已加入上传队列。本地保存与后台收到分别显示。');break;case'next-subject':mutate(x=>{x.subject=Math.min(2,x.subject+1);x.stage='ready'});break;case'end-candidate':mutate(x=>{x.stage='done';x.onsiteEnded=true});note('A的三科现场录制已结束。上传和材料核对继续保留独立状态。');break;case'interrupt':modal('异常结束本科','<p>中断片段保留原学员与科目，标为异常，不会当作连续完整录制。</p><label for="interrupt-reason">异常原因</label><textarea id="interrupt-reason" placeholder="请填写原因"></textarea>','保存异常片段','interrupt-confirm','danger');break;case'interrupt-confirm':if(!$('#interrupt-reason').value.trim())return;closeModal();mutate(x=>{x.stage='interrupted';x.interruptReason='已登记';x.abnormal=x.abnormal||[false,false,false];x.abnormal[x.subject]=true;x.local[x.subject]=true;x.upload[x.subject]='none'});note('异常片段已保留。需要负责人决定后续处置，不能直接作为完整评分材料。','warning');break;
case'confirm-video':if(s.upload[material]!=='received')return;mutate(x=>x.checked[material]=true);note('已确认A的本科评分用视频v1。');break;case'open-subject':if(!s.checked[material])return note('A的'+subjects[material]+'尚未核对通过，不能开放本科评卷。','warning');mutate(x=>x.opened[material]=true);note(subjects[material]+'材料条件检查通过，已开放给本科每位老师全部3名学员。');break;
case'play':videoPlaying=!videoPlaying;render();break;case'save-score':saveScore(false);break;case'save-next':saveScore(true);break;case'report-video':modal('报告视频问题','<label for="video-issue">问题描述</label><textarea id="video-issue" placeholder="例如：画面打不开或声音缺失"></textarea><p class="fine">提交问题不会给0分，也不会从应评名单中移除。</p>','登记问题','report-confirm');break;case'report-confirm':if(!$('#video-issue').value.trim())return;mutate(x=>x.scoreIssue[scoreKey(x)]=true);closeModal();note('视频问题已登记，当前评分任务保留待处理。','warning');break;
case'export':exportCSV('第一轮-成绩核对-未发布.csv',[['学员','作品朗读平均','新闻播报平均','话题评述平均','状态'],...people().map(p=>[p.name,...subjects.map((n,q)=>average(q,p.id)??'缺评未合分'),s.published?'已发布v'+s.publishVersion:'未发布'])]);note('核对表已导出。发布状态没有改变。');break;case'check-publish':if(!adminReady())return note('发布条件未满足：请处理缺评与材料开放状态。缺评不会按已有评分直接平均。','warning');mutate(x=>x.reviewRev=x.scoreRev);go('W08');break;case'publish-confirm':if(!adminReady())return;window.pendingPublishRev=s.scoreRev;modal('确认发布本次结果','<p>第一轮播音模拟考 · 3名学员。</p><p>每位学员仅看到本人三科平均分。将形成独立发布版本，核对表导出与本次发布无关。</p>','确认发布','publish-final');break;case'publish-final':{closeModal();const result=YF.publish(actorId,window.pendingPublishRev);note(result.ok?'成绩已发布 · v'+current().publishVersion+'。本人查询页已可查看。':result.reason,result.ok?'info':'warning');break}case'refresh-results':note(s.published?'已取得发布结果。':'当前仍未发布，请等待机构发布。');break;
case'preview-account':{const roles=[$('#role-monitor').checked&&'监考',$('#role-record').checked&&'录制'].filter(Boolean),scope=$('#scope-select').value;if(!roles.length)return note('至少保留一个岗位，或使用单独的停用与移交流程。','warning');window.accountDraft={roles,scope};modal('预览岗位与范围调整',`<dl class="kv"><dt>账号</dt><dd>工作人员甲</dd><dt>岗位</dt><dd>${roles.join('、')}</dd><dt>范围</dt><dd>${esc(scope)}</dd></dl><p class="fine">只有预览内容确认后才保存。当前未完任务需另行移交。</p>`,'确认保存调整','account-save');break}case'account-save':{const d=window.accountDraft;if(((s.handoff==='accepted'&&!s.onsiteEnded)||s.upload.some(x=>x==='failed'||x==='queued'))&&(d.scope!==s.scope||!d.roles.includes('录制'))){closeModal();return note('存在当前学员或待传文件。请先指定接手人并完成移交，本稿保留原授权。','warning')}closeModal();mutate(x=>{x.roleMonitor=d.roles.includes('监考');x.roleRecord=d.roles.includes('录制');x.scope=d.scope;x.accountRevision++;x.assigned=x.roleRecord});note('负责范围已保存，授权版本更新。');break}case'disable-account':if((s.handoff==='accepted'&&!s.onsiteEnded)||s.upload.some(x=>x==='failed'||x==='queued'))return note('账号还有当前学员或待传文件，请先完成移交。没有直接停用。','warning');modal('停用工作人员甲','<p>停用后不能领取新任务。已有文件不会被立即删除。</p>','确认停用','disable-confirm','danger');break;case'disable-confirm':closeModal();mutate(x=>x.accountActive=false);note('账号已停用。');break;case'permission-back':go(actor.home);break;default:break;}});
root.addEventListener('input',e=>{if(e.target.id==='score'&&actor.group==='teacher'){const v=e.target.value;inputChange=true;mutate(x=>x.drafts[scoreKey(x)]=v);inputChange=false;$('#score-status').className='save-status';$('#score-status').textContent='有未保存的输入'}});
root.addEventListener('change',e=>{const el=e.target;if(el.id==='admin-subject'&&actor.group==='admin'){adminSubject=el.value;render()}if(el.id==='admin-teacher'&&actor.group==='admin'){adminTeacher=el.value;render()}if(el.id==='monitor-filter'&&actor.group==='invigilator'){monitorFilter=el.value;render()}if(el.id==='role-filter'){role=el.value;render()}if(['grade-subject','grade-student'].includes(el.id)){if(dirtyScore()){const chosen=el.value;modal('切换评分任务','<p>当前输入尚未提交，会保留在原任务中。切换不会保存评分。</p>','保留输入并切换','switch-grade');window.pendingGrade={id:el.id,value:chosen};render()}else changeGrade(el.id,el.value)}});
function changeGrade(id,v){mutate(x=>{if(actor.group!=='teacher')return;if(id==='grade-subject'&&actor.subjects.includes(+v))x.scoreSub=+v;if(id==='grade-student'&&people().some(p=>p.id===v))x.student=v})}
document.addEventListener('click',e=>{if(e.target.dataset.action==='switch-grade'){const p=window.pendingGrade;closeModal();changeGrade(p.id,p.value)}});
let timerStart=0,timerAnchor=performance.now(),timerOffset=0;function updateTimer(){if(screen!=='A02'||current().stage!=='recording')return;const s=current();if(timerStart!==s.started){timerStart=s.started;timerOffset=Math.max(0,Date.now()-s.started);timerAnchor=performance.now()}const elapsed=Math.max(0,Math.floor((timerOffset+performance.now()-timerAnchor)/1000));const left=Math.max(0,120-elapsed);const el=$('#timer');if(el)el.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0')}
window.addEventListener('keydown',e=>{if(screen==='A02'&&current().stage==='recording'&&(e.key==='Escape'||e.key==='BrowserBack')){e.preventDefault();note('本科正在录制。若需结束，请使用“结束本科并保存”或登记异常。','warning')}});window.addEventListener('beforeunload',e=>{if(!preview&&screen==='A02'&&current().stage==='recording'){e.preventDefault();e.returnValue=''}});YF.subscribe(()=>{if(!inputChange)render()});render();if(!preview)setInterval(updateTimer,1000);if(parent!==window)parent.postMessage({type:'yf-screen',screen,actor:actorId,fixture:YF.fixture},'*');})();
